import { type } from "arktype";

export const LooseUser = type({
    name: "string"
});

export const RejectUser = type({
    name: "string",
    "+": "reject"
});

export const DeleteUser = type({
    name: "string",
    "+": "delete"
});

console.log("Loose:", LooseUser({ name: "a", extra: 1 }));
console.log("Reject:", RejectUser({ name: "a", extra: 1 }));
console.log("Delete:", DeleteUser({ name: "a", extra: 1 }));

